const texto = "Reunião marcada para 2026-09-16";
const regexComCaptura = /(\d{4})-(\d{2})-(\d{2})/;
const resultado = texto.match(regexComCaptura);
console.log(resultado[0]); // "2026-09-16"
console.log(resultado[1]); // "2026" (ano)
console.log(resultado[2]); // "09"   (mês)
console.log(resultado[3]); // "16"   (dia)

// Grupo não-capturante: participa na correspondência mas não aparece no resultado
const regexNaoCapturante = /(?:\d{4})-(\d{2})-(\d{2})/;
const resultado2 = texto.match(regexNaoCapturante);
console.log(resultado2[1]);      // "09" — o ano deixou de ocupar uma posição
console.log(resultado2.length);  // 3 (correspondência completa + 2 grupos)

// Uso típico de (?:...): apenas para agrupar uma alternância
const regexFicheiro = /^documento(?:\.pdf|\.docx|\.txt)$/;
console.log(regexFicheiro.test("documento.pdf")); // true

const regexData = /(?<ano>\d{4})-(?<mes>\d{2})-(?<dia>\d{2})/;
const match = "2026-09-16".match(regexData);

const { ano, mes, dia } = match.groups;
console.log(`${dia}/${mes}/${ano}`); // "16/09/2026"

// O mesmo grupo nomeado pode ser reutilizado diretamente no replace()
const reformatada = "2026-09-16".replace(regexData, "$<dia>/$<mes>/$<ano>");
console.log(reformatada); // "16/09/2026"

// Com matchAll(), cada correspondência traz o seu próprio objeto groups
const log = "erro em 2026-01-05 e novamente em 2026-03-12";
for (const { groups } of log.matchAll(new RegExp(regexData, "g"))) {
  console.log(`${groups.dia}/${groups.mes}/${groups.ano}`);
}

// Lookahead positivo encadeado: separador de milhares
const numero = "1234567890";
const comSeparadores = numero.replace(/\B(?=(?:\d{3})+(?!\d))/g, " ");
console.log(comSeparadores); // "1 234 567 890"

// Vários lookaheads a partir da mesma posição = várias condições em simultâneo
function validarPassword(password) {
  const regra = /^(?=.*[A-Z])(?=.*\d)(?!.*\s).{8,}$/;
  return regra.test(password);
}

console.log(validarPassword("Segura123"));   // true
console.log(validarPassword("fraca123"));    // false (sem maiúscula)
console.log(validarPassword("Com Espaco1"));  // false (contém espaço)

// Lookbehind positivo: obter o valor logo a seguir a um símbolo de euro
const preco = "Preço: €45,90";
const valor = preco.match(/(?<=€)[\d,]+/);
console.log(valor[0]); // "45,90"

// Lookbehind negativo: ignorar números já marcados com o símbolo de euro
const transacoes = "saldo: €1200, unidades: 30, ajuste: €50";
const semEuro = transacoes.match(/(?<!€)\b\d+\b/g);
console.log(semEuro); // ["30"]

// Backreference numerada: detetar palavras repetidas consecutivamente
const frase = "ela foi foi ao mercado e comprou comprou pão";
const repetidas = frase.match(/\b(\w+)\s+\1\b/gi);
console.log(repetidas); // ["foi foi", "comprou comprou"]

// Backreference nomeada: validar que a tag de fecho corresponde à de abertura
const regexTag = /^<(?<tag>\w+)>.*<\/\k<tag>>$/;
console.log(regexTag.test("<b>texto</b>")); // true
console.log(regexTag.test("<b>texto</i>")); // false

// Email: cobre a esmagadora maioria dos casos reais, mas não é a especificação completa (RFC 5322)
const regexEmail = /^[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}$/;
console.log(regexEmail.test("ana.silva@exemplo.pt")); // true
console.log(regexEmail.test("nome@dominio"));              // false — falta o domínio de topo

// Telefone português: fixo ou móvel, com indicativo internacional opcional
const regexTelefonePT = /^(?:\+351\s?)?[29]\d{8}$/;
console.log(regexTelefonePT.test("+351 912345678")); // true
console.log(regexTelefonePT.test("212345678"));       // true

// Data DD/MM/AAAA: valida o FORMATO, não valida o calendário
const regexDataPT = /^(?<dia>0[1-9]|[12]\d|3[01])\/(?<mes>0[1-9]|1[0-2])\/(?<ano>\d{4})$/;
console.log(regexDataPT.test("31/02/2026")); // true — mas 31 de fevereiro não existe!

