const regexData = /^(?<dia>\d{2})\/(?<mes>\d{2})\/(?<ano>\d{4})$/;
const match = "16/09/2026".match(regexData);
const { dia, mes, ano } = match.groups;
const resultado = `${ano}-${mes}-${dia}`;
console.log(resultado); // "2026-09-16"

function validarPassword(password) {
  const regra = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/;
  return regra.test(password);
}

console.log(validarPassword("Abcdef12")); // true
console.log(validarPassword("abcdef12")); // false (sem maiúscula)
console.log(validarPassword("Abc123"));   // false (menos de 8 caracteres)

const texto = "Saldo: 1200€, despesa: -350€, depósito: 900€, ajuste: -75€";
const positivos = texto.match(/(?<!-)\b\d+(?=€)/g);
console.log(positivos); // ["1200", "900"]

function temPalavraRepetida(texto) {
  const regex = /\b(?<palavra>\w+)\s+\k<palavra>\b/i;
  return regex.test(texto);
}

console.log(temPalavraRepetida("ela foi foi ao mercado")); // true
console.log(temPalavraRepetida("O o carro é novo"));       // true (case-insensitive)
console.log(temPalavraRepetida("isto é um teste simples")); // false
